public class AccountBalance {
    private long balanceCents;

    // Naive: balanceCents += cents is a read, an add and a write
    public void depositBroken(long cents) { balanceCents += cents; }

    // Fixed: one thread at a time, and readers take the same lock
    public synchronized void deposit(long cents) { balanceCents += cents; }
    public synchronized long balance() { return balanceCents; }
}

kotlin.src:
class AccountBalance {
    private var balanceCents = 0L

    // Naive: compiles to the same read, add and write
    fun depositBroken(cents: Long) { balanceCents += cents }

    // Fixed: Kotlin has no synchronized modifier; the annotation does the same job
    @Synchronized fun deposit(cents: Long) { balanceCents += cents }
    @Synchronized fun balance(): Long = balanceCents
}

