class PaymentDesk {
    private val recorded: MutableSet<String> = ConcurrentHashMap.newKeySet()

    fun handle(p: Payment) {
        if (p.id in recorded) return             // check
        bank.record(p)                           // about 80 ms
        recorded += p.id                         // act
    }
}

