void handle(Payment p) {
    // 1. claim the id: add() returns false if it was already there
    if (!recorded.add(p.id())) return;
    try {
        bank.record(p);                     // 2. record
    } catch (RuntimeException ex) {
        recorded.remove(p.id());            // 3. release on failure
        throw ex;
    }
}

